#include <Arduino.h>
#include <TM1637Display.h>
#include <math.h>

TM1637Display display(4, 5);
const float nearThresholdCm = 20.0f;

void setup() {
  pinMode(8, OUTPUT);
  digitalWrite(8, LOW);
  pinMode(2, INPUT);
  pinMode(13, OUTPUT);
  pinMode(9, OUTPUT);
  digitalWrite(13, LOW);
  analogWrite(9, 0);
  display.setBrightness(7);
  display.clear();
}

void loop() {
  digitalWrite(8, LOW);
  delayMicroseconds(2);
  digitalWrite(8, HIGH);
  delayMicroseconds(10);
  digitalWrite(8, LOW);
  unsigned long duration = pulseIn(2, HIGH, 30000UL);
  if (duration != 0) {
    float cm = duration * 0.0343f / 2.0f;
    display.showNumberDec((int)lroundf(cm), false);
    digitalWrite(13, cm < nearThresholdCm ? HIGH : LOW);
    float duty = 255.0f * (1.0f - cm / 400.0f);
    if (duty < 0.0f) duty = 0.0f;
    if (duty > 255.0f) duty = 255.0f;
    analogWrite(9, (int)lroundf(duty));
  }
  delay(100);
}
